export function ViewTransitions({ children }: { children: React.ReactNode }) {
  return (
    <>
      {children}
      <style dangerouslySetInnerHTML={{ __html: `
        @media (prefers-reduced-motion: no-preference) {
          ::view-transition-old(root),
          ::view-transition-new(root) {
            animation-duration: 300ms;
            animation-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
          }
          ::view-transition-old(root) {
            animation-name: slide-out;
          }
          ::view-transition-new(root) {
            animation-name: slide-in;
          }
          @keyframes slide-out {
            from { transform: translateX(0); opacity: 1; }
            to { transform: translateX(-30%); opacity: 0; }
          }
          @keyframes slide-in {
            from { transform: translateX(30%); opacity: 0; }
            to { transform: translateX(0); opacity: 1; }
          }
          ::view-transition-old(product-image),
          ::view-transition-new(product-image) {
            animation-duration: 400ms;
            animation-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
          }
          @keyframes fade-in-skeleton {
            from { opacity: 0; }
            to { opacity: 1; }
          }
          @keyframes fade-out-skeleton {
            from { opacity: 1; }
            to { opacity: 0; }
          }
          .skeleton-image {
            animation: pulse 1.5s ease-in-out infinite, fade-in-skeleton 200ms ease-out;
          }
          .skeleton-content {
            animation: fade-in-skeleton 300ms ease-out;
          }
          .content-fade-in {
            animation: fade-in-skeleton 400ms ease-out;
          }
        }
        @media (prefers-reduced-motion: reduce) {
          ::view-transition-old(root),
          ::view-transition-new(root),
          ::view-transition-old(product-image),
          ::view-transition-new(product-image) {
            animation: none;
          }
          .skeleton-image,
          .skeleton-content,
          .content-fade-in {
            animation: none;
          }
        }
      `}} />
    </>
  )
}

